20	declare_lint_rule! {
21	    /// Enforce that anchors have content and that the content is accessible to screen readers.
22	    ///
23	    /// Accessible means the content is not hidden using the `aria-hidden` attribute.
24	    /// Anchor tags should have text content that describes the link destination for screen reader users.
25	    /// Alternatively, the anchor can have an accessible name via the `aria-label` or `title` attribute.
26	    ///
27	    /// :::note
28	    /// In `.html` files, this rule matches element names case-insensitively (e.g., `<A>`, `<a>`).
29	    ///
30	    /// In component-based frameworks (Vue, Svelte, Astro), only lowercase element names are checked.
31	    /// PascalCase variants like `<A>` are assumed to be custom components and are ignored.
32	    /// :::
33	    ///
34	    /// ## Examples
35	    ///
36	    /// ### Invalid
37	    ///
38	    /// ```html,expect_diagnostic
39	    /// <a></a>
40	    /// ```
41	    ///
42	    /// ```html,expect_diagnostic
43	    /// <a>   </a>
44	    /// ```
45	    ///
46	    /// ```html,expect_diagnostic
47	    /// <a aria-hidden="true">content</a>
48	    /// ```
49	    ///
50	    /// ```html,expect_diagnostic
51	    /// <a><span aria-hidden="true">content</span></a>
52	    /// ```
53	    ///
54	    /// ### Valid
55	    ///
56	    /// ```html
57	    /// <a>content</a>
58	    /// ```
59	    ///
60	    /// ```html
61	    /// <a><span>content</span></a>
62	    /// ```
63	    ///
64	    /// ```html
65	    /// <a><span aria-hidden="true"></span>content</a>
66	    /// ```
67	    ///
68	    /// ```html
69	    /// <a aria-label="Navigate to home"></a>
70	    /// ```
71	    ///
72	    /// ```html
73	    /// <a title="Home page"></a>
74	    /// ```
75	    ///
76	    /// ## Accessibility guidelines
77	    ///
78	    /// - [WCAG 2.4.4](https://www.w3.org/WAI/WCAG21/Understanding/link-purpose-in-context)
79	    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
80	    ///
81	    pub UseAnchorContent {
82	        version: "2.4.0",
83	        name: "useAnchorContent",
84	        language: "html",
85	        sources: &[RuleSource::EslintJsxA11y("anchor-has-content").same()],
86	        recommended: true,
87	        severity: Severity::Error,
88	        fix_kind: FixKind::Unsafe,
89	    }
90	}
91	
92	/// State to track whether the issue is aria-hidden on the anchor itself
93	pub struct UseAnchorContentState {
94	    aria_hidden_attribute: Option<HtmlAttribute>,
95	}
96	
97	impl Rule for UseAnchorContent {
98	    type Query = Ast<AnyHtmlElement>;
99	    type State = UseAnchorContentState;
100	    type Signals = Option<Self::State>;
101	    type Options = UseAnchorContentOptions;
102	
103	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
104	        let node = ctx.query();
105	
106	        // Check if element is an anchor tag
107	        // In HTML files, tag names are case-insensitive
108	        // In component frameworks (Vue, Svelte, Astro), only lowercase is checked
109	        let element_name = node.name()?;
110	        let source_type = ctx.source_type::<HtmlFileSource>();
111	        let is_anchor = if source_type.is_html() {
112	            element_name.text().eq_ignore_ascii_case("a")
113	        } else {
114	            element_name.text() == "a"
115	        };
116	        if !is_anchor {
117	            return None;
118	        }
119	
120	        // Check if the anchor itself has aria-hidden attribute
121	        if let Some(aria_hidden_attr) = get_truthy_aria_hidden_attribute(node) {
122	            return Some(UseAnchorContentState {
123	                aria_hidden_attribute: Some(aria_hidden_attr),
124	            });
125	        }
126	
127	        // Check if anchor has accessible name via aria-label or title
128	        if has_accessible_name(node) {
129	            return None;
130	        }
131	
132	        // Handle self-closing anchors - they have no content
133	        if node.as_html_element().is_none() {
134	            return Some(UseAnchorContentState {
135	                aria_hidden_attribute: None,
136	            });
137	        }
138	
139	        let html_element = node.as_html_element()?;
140	        // Skip analysis if we can't fully parse the element to avoid false positives
141	        if html_element.opening_element().is_err() {
142	            return None;
143	        }
144	
145	        // Check if the anchor has accessible content
146	        let is_astro = source_type.is_astro();
147	        if has_accessible_content(&html_element.children(), is_astro) {
148	            return None;
149	        }
150	
151	        // No accessible content found - emit diagnostic
152	        Some(UseAnchorContentState {
153	            aria_hidden_attribute: None,
154	        })
155	    }
156	
157	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
158	        let node = ctx.query();
159	        let diagnostic = RuleDiagnostic::new(
160	            rule_category!(),
161	            node.syntax().text_trimmed_range(),
162	            markup! {
163	                "Provide screen reader accessible content when using "<Emphasis>"a"</Emphasis>" elements."
164	            },
165	        )
166	        .note(markup! {
167	            "All links on a page should have content that is accessible to screen readers."
168	        })
169	        .note(markup! {
170	            "Accessible content refers to digital content that is designed and structured in a way that makes it easy for people with disabilities to access, understand, and interact with using assistive technologies."
171	        })
172	        .note(markup! {
173	            "Follow these links for more information,\n "<Hyperlink href="https://www.w3.org/WAI/WCAG21/Understanding/link-purpose-in-context">"WCAG 2.4.4"</Hyperlink>"\n "<Hyperlink href="https://www.w3.org/WAI/WCAG21/Understanding/name-role-value">"WCAG 4.1.2"</Hyperlink>""
174	        });
175	
176	        Some(diagnostic)
177	    }
178	
179	    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<HtmlRuleAction> {
180	        let aria_hidden = state.aria_hidden_attribute.as_ref()?;
181	        let mut mutation = ctx.root().begin();
182	        mutation.remove_node(aria_hidden.clone());
183	
184	        Some(HtmlRuleAction::new(
185	            ctx.metadata().action_category(ctx.category(), ctx.group()),
186	            ctx.metadata().applicability(),
187	            markup! { "Remove the "<Emphasis>"aria-hidden"</Emphasis>" attribute to allow the anchor element and its content visible to assistive technologies." }.to_owned(),
188	            mutation,
189	        ))
190	    }
191	}
