12	declare_lint_rule! {
13	    /// Enforce that the `accesskey` attribute is not used on any HTML element.
14	    ///
15	    /// The `accesskey` assigns a keyboard shortcut to the current element. However, the `accesskey` value
16	    /// can conflict with keyboard commands used by screen readers and keyboard-only users, which leads to
17	    /// inconsistent keyboard actions across applications. To avoid accessibility complications,
18	    /// this rule suggests users remove the `accesskey` attribute on elements.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```html,expect_diagnostic
25	    /// <input type="submit" accesskey="s" value="Submit" />
26	    /// ```
27	    ///
28	    /// ```html,expect_diagnostic
29	    /// <a href="https://webaim.org/" accesskey="w">WebAIM.org</a>
30	    /// ```
31	    ///
32	    /// ```html,expect_diagnostic
33	    /// <button accesskey="n">Next</button>
34	    /// ```
35	    ///
36	    /// ## Resources
37	    ///
38	    /// - [WebAIM: Keyboard Accessibility - Accesskey](https://webaim.org/techniques/keyboard/accesskey#spec)
39	    /// - [MDN `accesskey` documentation](https://developer.mozilla.org/docs/Web/HTML/Global_attributes/accesskey)
40	    ///
41	    pub NoAccessKey {
42	        version: "2.4.0",
43	        name: "noAccessKey",
44	        language: "html",
45	        sources: &[RuleSource::EslintJsxA11y("no-access-key").same(), RuleSource::HtmlEslint("no-accesskey-attrs").same()],
46	        recommended: true,
47	        severity: Severity::Error,
48	        fix_kind: FixKind::Unsafe,
49	    }
50	}
51	
52	impl Rule for NoAccessKey {
53	    type Query = Ast<HtmlAttribute>;
54	    type State = ();
55	    type Signals = Option<Self::State>;
56	    type Options = NoAccessKeyOptions;
57	
58	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
59	        let node = ctx.query();
60	        if is_accesskey_attribute(node) {
61	            return Some(());
62	        }
63	
64	        None
65	    }
66	
67	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
68	        let node = ctx.query();
69	        Some(
70	            RuleDiagnostic::new(
71	                rule_category!(),
72	                node.syntax().text_trimmed_range(),
73	                markup! {
74	                    "Avoid the "<Emphasis>"accesskey"</Emphasis>" attribute to reduce inconsistencies between \
75	                    keyboard shortcuts and screen reader keyboard commands."
76	                },
77	            ).note(
78	                markup! {
79	                    "Assigning keyboard shortcuts using the "<Emphasis>"accesskey"</Emphasis>" attribute leads to \
80	                    inconsistent keyboard actions across applications."
81	                },
82	            )
83	        )
84	    }
85	
86	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<HtmlRuleAction> {
87	        let node = ctx.query();
88	        let mut mutation = ctx.root().begin();
89	        mutation.remove_node(node.clone());
90	        Some(HtmlRuleAction::new(
91	            ctx.metadata().action_category(ctx.category(), ctx.group()),
92	            ctx.metadata().applicability(),
93	            markup! { "Remove the "<Emphasis>"accesskey"</Emphasis>" attribute." }.to_owned(),
94	            mutation,
95	        ))
96	    }
97	}
98	
99	fn is_accesskey_attribute(node: &HtmlAttribute) -> bool {
100	    node.name().is_ok_and(|name| {
101	        name.value_token()
102	            .is_ok_and(|value_token| value_token.text_trimmed() == "accesskey")
103	    })
104	}
