140	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
141	        let node = ctx.query();
142	
143	        // Only check `<a>` elements. In HTML files, tag names are case-insensitive;
144	        // in component frameworks (Vue, Svelte, Astro) only lowercase is checked so
145	        // that PascalCase components (e.g. `<Link>`) are ignored.
146	        let element_name = node.name()?;
147	        let source_type = ctx.source_type::<HtmlFileSource>();
148	        let is_anchor = if source_type.is_html() {
149	            element_name.text().eq_ignore_ascii_case("a")
150	        } else {
151	            element_name.text() == "a"
152	        };
153	        if !is_anchor {
154	            return None;
155	        }
156	
157	        // `href` can be a plain attribute or a Vue binding (`:href` / `v-bind:href`).
158	        let href_attribute = node.find_attribute_or_vue_binding("href");
159	
160	        // The `onclick` handler is only meaningful in HTML, Astro and Svelte files.
161	        // Vue event directives (e.g. `@click`) are not treated as an equivalent.
162	        let on_click_attribute = if source_type.is_vue() {
163	            None
164	        } else {
165	            node.find_attribute_by_name("onclick")
166	        };
167	
168	        match (href_attribute, on_click_attribute) {
169	            (Some(href_attribute), Some(on_click_attribute)) => {
170	                // A dynamic binding (Vue `:href`) is always a valid href.
171	                if let AnyHtmlAttribute::HtmlAttribute(href_attribute) = &href_attribute
172	                    && is_invalid_href(href_attribute)
173	                {
174	                    return Some(UseValidAnchorState::CantBeAnchor(
175	                        on_click_attribute.syntax().text_trimmed_range(),
176	                    ));
177	                }
178	            }
179	            (Some(href_attribute), None) => {
180	                if let AnyHtmlAttribute::HtmlAttribute(href_attribute) = &href_attribute
181	                    && is_invalid_href(href_attribute)
182	                {
183	                    return Some(UseValidAnchorState::IncorrectHref(
184	                        href_attribute.syntax().text_trimmed_range(),
185	                    ));
186	                }
187	            }
188	            (None, Some(on_click_attribute)) => {
189	                return Some(UseValidAnchorState::CantBeAnchor(
190	                    on_click_attribute.syntax().text_trimmed_range(),
